import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";var i=JSON.parse(`{"title":"Networks & Freedom","description":"Proxies, VLESS tunnels, subscription panels and edge deployments — Reza Bazdar builds infrastructure for an open internet.","frontmatter":{"title":"Networks & Freedom","description":"Proxies, VLESS tunnels, subscription panels and edge deployments — Reza Bazdar builds infrastructure for an open internet."},"headers":[],"relativePath":"en/about/networking/index.md","filePath":"en/about/networking/index.md"}`),a={name:`en/about/networking/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="networks-freedom" tabindex="-1">Networks &amp; Freedom <a class="header-anchor" href="#networks-freedom" aria-label="Permalink to “Networks &amp; Freedom”">​</a></h1><p>I grew up behind filters. Where I live, parts of the internet are routinely unreachable — not because servers are down, but because someone decided they should be. That reality turned networking from a hobby into a survival skill, and the survival skill into a specialty: building infrastructure that keeps people connected.</p><p>My work in this area is practical rather than theoretical. I design and operate <strong>VLESS tunnels and proxy panels</strong>, manage multi-user subscription systems with Clash, v2ray and sing-box compatibility, and deploy edge infrastructure across Cloudflare Workers, Hugging Face Spaces, Railway, Render, Fly.io and Koyeb. Each of my panel projects — <a href="/Usf/en/projects/usf-panel/">Usf Panel</a>, usf-edge, edge-pp, Render-usf — attacks the same problem from a different platform, because blocking is an arms race and single points of failure get people cut off.</p><h2 id="what-i-actually-build" tabindex="-1">What I actually build <a class="header-anchor" href="#what-i-actually-build" aria-label="Permalink to “What I actually build”">​</a></h2><ul><li><strong>Tunnel panels</strong> — multi-user VLESS management with subscription links, traffic stats and one-command deploys.</li><li><strong>Edge deployments</strong> — proxy state on Cloudflare KV across 300+ PoPs, zero cold starts, no servers to seize.</li><li><strong>Diagnostics</strong> — pure-Go tooling like <a href="/Usf/en/projects/netpilot/">NetPilot</a> for port scanning, TCP ping and HTTP health checks.</li><li><strong>Resilience patterns</strong> — multi-platform redundancy so one takedown never equals zero access.</li></ul><div class="info custom-block"><p class="custom-block-title">Why this matters</p><p>In an environment where connectivity itself is contested, a proxy panel is not a gadget — it is a lifeline for work, education and free information. I treat it with the seriousness of critical infrastructure.</p></div><h2 id="the-mindset" tabindex="-1">The mindset <a class="header-anchor" href="#the-mindset" aria-label="Permalink to “The mindset”">​</a></h2><p>Networking taught me how systems fail: gracefully, partially, and always at the worst moment. It taught me to read packet captures the way other people read error messages, to distrust &quot;temporarily blocked&quot;, and to always have a second path, a third fallback and a fourth idea. Those instincts bleed into everything else I build — redundant APIs, failover model routing, and panels that assume the network is hostile.</p><p>If your project needs to survive a hostile network — or you just want your stack to stop falling over when a region goes dark — that is exactly the kind of problem I enjoy most.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};